/**
 * @title Dashboard with key numbers, a chart and a table
 * @description An inset sidebar app: four key numbers with trends, visitors over time with a range switch, and a sortable table of documents.
 * @route /dashboard
 * @height 900
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { Button } from "@/components/ui/button";
import { StatCard } from "@/components/ui/display";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { SiteHeader } from "@/components/site-header";
import { VisitorsChart } from "@/components/visitors-chart";
import { DocumentsTable } from "@/components/documents-table";

export default function Page() {
  return (
    <SidebarProvider>
      <DashboardSidebar current="Dashboard" />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Dashboard" }]} actions={<Button size="sm" leadingIcon="plus">Quick create</Button>} />
        <div className="flex flex-1 flex-col gap-6 p-4 md:p-6">
          <h1 className="text-heading-h2">Dashboard</h1>
          <section aria-label="Key numbers" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <StatCard label="Total revenue" value="$1,250.00" trend={{ direction: "positive", value: "+12.5%" }} context="Trending up this month" />
            <StatCard label="New customers" value="1,234" trend={{ direction: "negative", value: "−20%" }} context="Down this period" />
            <StatCard label="Active accounts" value="45,678" trend={{ direction: "positive", value: "+12.5%" }} context="Strong retention" />
            <StatCard label="Growth rate" value="4.5%" trend={{ direction: "positive", value: "+4.5%" }} context="Meets projections" />
          </section>
          <VisitorsChart />
          <DocumentsTable />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BarChart3, Camera, Database, FileText, FolderKanban, Gauge, HelpCircle, LayoutDashboard, ListChecks, Search, Settings, Users } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarRail,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const main = [
  { title: "Dashboard", icon: LayoutDashboard }, { title: "Lifecycle", icon: ListChecks }, { title: "Analytics", icon: BarChart3 },
  { title: "Projects", icon: FolderKanban }, { title: "Team", icon: Users },
];
const documents = [{ title: "Data library", icon: Database }, { title: "Reports", icon: FileText }, { title: "Capture", icon: Camera }];
const secondary = [{ title: "Settings", url: "#", icon: Settings }, { title: "Get help", url: "#", icon: HelpCircle }, { title: "Search", url: "#", icon: Search }];

/** The app sidebar the dashboard, settings and table blocks share. Pass the current page's title. */
export function DashboardSidebar({ current = "Dashboard", variant = "inset" }: { current?: string; variant?: "sidebar" | "inset" }) {
  return (
    <Sidebar collapsible="icon" variant={variant} label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Workspace" logo={Gauge} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <SidebarGroup>
            <SidebarMenu>
              {main.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Documents</SidebarGroupLabel>
            <SidebarMenu>
              {documents.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary.map((s) => ({ ...s }))} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

"use client";
import { useState } from "react";
import { SegmentedControl } from "@/components/ui/navigation";
import { AreaChart } from "@/components/area-chart";

const all = Array.from({ length: 90 }, (_, i) => {
  const d = new Date(2026, 6, 1 + i);
  const wave = Math.sin(i / 6) * 90 + Math.cos(i / 13) * 60;
  return { label: d.toLocaleDateString("en-US", { month: "short", day: "numeric" }), values: [Math.round(260 + wave + (i % 7) * 12), Math.round(180 + wave * 0.6 + (i % 5) * 10)] };
});
const ranges = { "90d": 90, "30d": 30, "7d": 7 } as const;

export function VisitorsChart() {
  const [range, setRange] = useState<keyof typeof ranges>("90d");
  return (
    <section aria-labelledby="visitors-title" className="flex flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)]">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex flex-col gap-1">
          <h2 id="visitors-title" className="text-heading-h4">Total visitors</h2>
          <p className="text-body-small text-fg-secondary">Desktop and mobile, last {ranges[range]} days</p>
        </div>
        <div className="[&_[role=radio]]:min-w-fit">
          <SegmentedControl label="Time range" value={range} onChange={setRange}
            options={[{ value: "90d", label: "90 days" }, { value: "30d", label: "30 days" }, { value: "7d", label: "7 days" }]} />
        </div>
      </div>
      <AreaChart title={`Visitors per day, last ${ranges[range]} days`} series={["Desktop", "Mobile"]} data={all.slice(-ranges[range])} />
    </section>
  );
}

/** A small area chart in plain SVG, coloured with the DX data-viz tokens. Screen readers get the numbers as a table.
 *  For bigger needs, swap in a chart library and keep the colours: var(--ds-color-dataviz-series-N). */
export function AreaChart({ title, series, data, height = 240, format = (n: number) => n.toLocaleString("en-US") }: {
  title: string;
  series: string[];
  data: { label: string; values: number[] }[];
  height?: number;
  format?: (n: number) => string;
}) {
  const W = 100, H = 40;
  const max = Math.max(...data.flatMap((d) => d.values)) * 1.1 || 1;
  const x = (i: number) => (i / Math.max(data.length - 1, 1)) * W;
  const y = (v: number) => H - (v / max) * H;
  const line = (s: number) => data.map((d, i) => `${i ? "L" : "M"}${x(i).toFixed(2)},${y(d.values[s]).toFixed(2)}`).join(" ");
  const every = Math.ceil(data.length / 6);
  const ticks = [0, 0.25, 0.5, 0.75, 1].map((t) => Math.round(max * t));
  return (
    <figure className="flex flex-col gap-3">
      <figcaption className="sr-only">{title}</figcaption>
      <div className="flex gap-2">
        <div aria-hidden className="flex flex-col justify-between py-0 text-end text-caption-default text-fg-secondary tabular-nums" style={{ height }}>
          {[...ticks].reverse().map((t) => <span key={t} className="-my-2 leading-4">{format(t)}</span>)}
        </div>
        <svg aria-hidden viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="min-w-0 flex-1 overflow-visible" style={{ height }}>
          {ticks.map((t) => <line key={t} x1="0" x2={W} y1={y(t)} y2={y(t)} stroke="var(--ds-color-border-default)" strokeWidth="1" vectorEffect="non-scaling-stroke" />)}
          {series.map((_, s) => (
            <g key={s}>
              <path d={`${line(s)} L${W},${H} L0,${H} Z`} fill={`var(--ds-color-dataviz-series-${s + 1})`} fillOpacity={0.14} />
              <path d={line(s)} fill="none" stroke={`var(--ds-color-dataviz-series-${s + 1})`} strokeWidth="2" vectorEffect="non-scaling-stroke" strokeLinejoin="round" />
            </g>
          ))}
        </svg>
      </div>
      <div aria-hidden className="flex justify-between ps-10 text-caption-default text-fg-secondary">
        {data.filter((_, i) => i % every === 0).map((d) => <span key={d.label}>{d.label}</span>)}
      </div>
      {series.length > 1 && (
        <ul aria-hidden className="flex flex-wrap justify-center gap-4 text-caption-default text-fg-secondary">
          {series.map((s, i) => <li key={s} className="flex items-center gap-1.5"><span className="size-2.5 rounded-sm" style={{ background: `var(--ds-color-dataviz-series-${i + 1})` }} />{s}</li>)}
        </ul>
      )}
      <table className="sr-only">
        <caption>{title}</caption>
        <thead><tr><th scope="col">Period</th>{series.map((s) => <th key={s} scope="col">{s}</th>)}</tr></thead>
        <tbody>{data.map((d) => <tr key={d.label}><th scope="row">{d.label}</th>{d.values.map((v, i) => <td key={i}>{format(v)}</td>)}</tr>)}</tbody>
      </table>
    </figure>
  );
}

"use client";
import { useState } from "react";
import { Badge } from "@/components/ui/feedback";
import { Table, type SortDir } from "@/components/ui/data";

type Row = { id: string; title: string; type: string; status: "Done" | "In progress" | "Not started"; target: number; limit: number; reviewer: string };
const rows: Row[] = [
  { id: "1", title: "Cover page", type: "Cover page", status: "In progress", target: 18, limit: 5, reviewer: "Eddie Lake" },
  { id: "2", title: "Table of contents", type: "Table of contents", status: "Done", target: 29, limit: 24, reviewer: "Eddie Lake" },
  { id: "3", title: "Executive summary", type: "Narrative", status: "Done", target: 10, limit: 13, reviewer: "Eddie Lake" },
  { id: "4", title: "Technical approach", type: "Narrative", status: "Done", target: 27, limit: 23, reviewer: "Jamik Tashpulatov" },
  { id: "5", title: "Design", type: "Narrative", status: "In progress", target: 2, limit: 16, reviewer: "Jamik Tashpulatov" },
  { id: "6", title: "Capabilities", type: "Narrative", status: "In progress", target: 20, limit: 8, reviewer: "Jamik Tashpulatov" },
  { id: "7", title: "Integration with existing systems", type: "Narrative", status: "Not started", target: 19, limit: 21, reviewer: "Assign reviewer" },
];
const tone = { Done: "success", "In progress": "info", "Not started": "neutral" } as const;

export function DocumentsTable() {
  const [sort, setSort] = useState<{ key: string; direction: SortDir } | null>({ key: "title", direction: "ascending" });
  return (
    <Table<Row>
      caption="Documents"
      rows={rows}
      rowKey={(r) => r.id}
      sort={sort}
      onSortChange={setSort}
      columns={[
        { key: "title", header: "Header", sortable: true },
        { key: "type", header: "Section type", sortable: true },
        { key: "status", header: "Status", sortable: true, render: (r) => <Badge tone={tone[r.status]}>{r.status}</Badge> },
        { key: "target", header: "Target", numeric: true, sortable: true },
        { key: "limit", header: "Limit", numeric: true, sortable: true },
        { key: "reviewer", header: "Reviewer", render: (r) => <span className={r.reviewer === "Assign reviewer" ? "text-fg-secondary" : ""}>{r.reviewer}</span> },
      ]}
    />
  );
}
